            if (tmp == a[0]) {
                System.out.println("YES");
                return;
            }
        }
        for (tb = 0; tb < a[1]; tb++) {
            int tmp = a[3] - (tb * a[5]);
            if (tmp == a[0]) {
                System.out.println("YES");
                return;
            }
        }
        for (ta = 0; ta < a[1]; ta++) {
            for (tb = 0; tb < a[1]; tb++) {
                int tmp = (a[2] - (ta * a[4])) + (a[3] - (tb * a[5]));
                if (tmp == a[0]) {
                    System.out.println("YES");
                    return;
                }
            }
        }
        System.out.println("NO");
    }
}

